];
const scolor = 'black'
// const fcolor = ['white','ghostwhite','cornsilk', 'snow','azure','ivory']
// const scolor = ['red','yellow','blue','orange','green', 'purple'];
const arcIncr = 3;
// let radius;
// let hex;
