function startOver() {
  background(15);
  let radius = round(random() * 120 + 80);
  let cols = round(width / radius / 2) + 1;
  let rows = round(height / radius) + 2;
  let fan = new handFan(radius)
  let cidx = ~~random(0, colors.length / 2) * 2;

  for (let col = 0; col < cols; col++) {
    let angle = 180 * (col % 2);
    for (let row = 0; row < rows; row++) {
      let angle2 = angle + 90 * (row % 2);
      let xOffset = (row % 2) * radius;
      if (round(row / 2) % 2 === 0) {
        angle2 += 180;
      }
      let x = col * radius * 2 + xOffset;
      let y = row * radius;
      let pick = ~~random(1,5)
      switch (pick) {
        case 0:
          fan.draw0(x, y, angle2, cidx);
          break;
        case 1:
          fan.draw1(x, y, angle2, cidx);
          break;
        case 2:
          fan.draw2(x, y, angle2, cidx);
          break;
        case 3:
          fan.draw3(x, y, angle2, cidx);
          break;
        case 4:
          fan.draw4(x, y, angle2, cidx);
          break;
      }
    }
  }
}

class handFan {
  constructor(radius) {
    this.radius = radius;
    this.points = [];
    this.layers = ~~random(4, 10);
    let x, y;

    for (let angle = 180; angle < 360; angle += (Math.max(0.001, Math.abs(arcIncr)) || 1)) {
      x = radius * cos(angle);
      y = radius * sin(angle);
      this.points.push(new Point(x, y));
    }
    for (let angle = 270; angle > 180; angle -= arcIncr) {
      x = radius * cos(angle);
      y = radius * sin(angle);
      this.points.push(new Point(x + radius, y + radius));
    }
    for (let angle = 360; angle > 270; angle -= arcIncr) {
      x = radius * cos(angle);
      y = radius * sin(angle);
      this.points.push(new Point(x - radius, y + radius));
    }
  }

  draw0(x, y, pos, cidx) {
    push();
    translate(x, y);
    rotate(pos);
    strokeWeight(0.25);
    let odd = false;
    stroke(scolor);
    // let cidx = ~~random(0, colors.length / 2) * 2;

    stroke(scolor[0]);
    fill(random(colors));
    beginShape();
    for (const p of this.points) {
      vertex(p.x, p.y);
    }
    endShape();
    endShape();
    pop();
  }

  draw1(x, y, pos, cidx) {
    push();
    translate(x, y);
    rotate(pos);
    const seg = 12;

    let odd = false;
    stroke(scolor);
    // let cidx = ~~random(0, colors.length / 2) * 2;

    for (let n = 0; n < this.points.length; n += (Math.max(0.001, Math.abs(arcIncr)) || 1)) {
      let c0 = odd ? colors[cidx + 1] : colors[cidx];
      fill(c0);
      beginShape();
      vertex(0, 0);
      for (let m = 0; m < this.layers + arcIncr; m += 1) {
        if (n + m < this.points.length) {
          vertex(this.points[n + m].x, this.points[n + m].y);
        }
      }
      vertex(0, 0);
      endShape(CLOSE);
      odd = odd === true ? false : true;
      fill(c0);
    }
    pop();
  }

  draw2(x, y, pos, cidx) {
    let x0, y0;
    push();
    translate(x, y);
    rotate(pos);
    let pt;
    stroke(scolor);
    let odd = false;
    stroke(scolor);
    // let cidx = ~~random(0, colors.length / 2) * 2;
    for (let n = 0; n < this.layers; n += 1) {
      let c0 = odd ? colors[cidx + 1] : colors[cidx];
      fill(c0);
      beginShape();
      for (const p of this.points) {
        x0 = lerp(0, p.x, 1 - n / this.layers);
        vertex(x0, p.y);
      }
      endShape();
      odd = odd === true ? false : true;
    }
    pop();
  }

  draw3(x, y, pos, cidx) {
    let x0, y0;
    push();
    translate(x, y);
    rotate(pos);
    let pt;
    let odd = false;
    stroke(scolor);
    // let cidx = ~~random(0, colors.length / 2) * 2;
    for (let n = 0; n < this.layers; n += 1) {
      let c0 = odd ? colors[cidx + 1] : colors[cidx];
      fill(c0);
      beginShape();
      for (const p of this.points) {
        x0 = lerp(0, p.x, 1 - n / this.layers);
        y0 = lerp(0, p.y, 1 - n / this.layers);
        vertex(x0, y0);
      }
      endShape();
      odd = odd === true ? false : true;
    }
    pop();
  }

  draw4(x, y, pos, cidx) {
    let x0, y0;
    push();
    translate(x, y);
    rotate(pos);
    let pt;
    let odd = false;
    stroke(scolor);
    // let cidx = ~~random(0, colors.length / 2) * 2;
    for (let n = 0; n < this.layers; n += 1) {
      let c0 = odd ? colors[cidx + 1] : colors[cidx];
      fill(c0);
      beginShape();
      for (const p of this.points) {
        y0 = lerp(0, p.y, 1 - n / this.layers);
        vertex(p.x, y0);
      }
      endShape();
      odd = odd === true ? false : true;
    }
    pop();
  }
}


